249	    /** Fixed city-to-region table used to derive an owner's region for its customer code. */
250	    private static final java.util.Map<String, String> CITY_REGION = java.util.Map.of(
251	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
252	
253	    /** Region to inclusive 4-digit postcode range {low, high}, preferred over the city table
254	     *  when deriving an owner's region. */
255	    private static final java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
256	        "NSW", new int[] {2000, 2099},
257	        "VIC", new int[] {3000, 3099},
258	        "QLD", new int[] {4000, 4099});
259	
260	    /**
261	     * Builds an owner's customer code formatted {@code '<REGION>-<HASH8>'}, where REGION is the
262	     * region code derived from the owner's postcode (see {@link #deriveRegion(Owner)}) and HASH8 is
263	     * the first 8 upper-case hex characters of the SHA-256 digest over the owner's normalized
264	     * telephone concatenated with its last name (e.g. {@code 'NSW-1A2B3C4D'}). The old per-city
265	     * sequence numbers have been dropped: the identity is now purely region-and-hash.
266	     *
267	     * <p>When the computed code collides with an existing owner's {@code customerCode}, {@code '-<n>'}
268	     * is appended with the smallest {@code n} of 2 or more that makes it unique, so distinct owners
269	     * always receive distinct customer codes.
270	     */
271	    private String generateCustomerCode(Owner owner) {
272	        String base = String.format("%s-%s", deriveRegion(owner), hash8(owner));
273	        Set<String> existing = ownerRepository.findAll().stream()
274	            .map(Owner::getCustomerCode)
275	            .filter(Objects::nonNull)
276	            .collect(Collectors.toSet());
277	        if (!existing.contains(base)) {
278	            return base;
279	        }
280	        for (int n = 2; ; n++) {
281	            String candidate = base + "-" + n;
282	            if (!existing.contains(candidate)) {
283	                return candidate;
284	            }
285	        }
286	    }
287	
288	    /**
289	     * Derives an owner's region code, preferring the postcode: the region whose inclusive 4-digit
290	     * range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099) contains the postcode is used first. When
291	     * the postcode is absent or in no known range, it falls back to the fixed city-to-region table
292	     * (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD), returning {@code 'UNKNOWN'} when the
293	     * city is not in the table.
294	     */
295	    private static String deriveRegion(Owner owner) {
296	        String postcode = owner.getPostcode();
297	        if (postcode != null && postcode.matches("^[0-9]{4}$")) {
298	            int value = Integer.parseInt(postcode);
299	            for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
300	                int[] range = entry.getValue();
301	                if (value >= range[0] && value <= range[1]) {
302	                    return entry.getKey();
303	                }
304	            }
305	        }
306	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
307	    }
308	
309	    /**
310	     * Computes an owner's identity hash as the first 8 upper-case hex characters of the SHA-256
311	     * digest over its normalized telephone concatenated with its last name.
312	     */
313	    private static String hash8(Owner owner) {
314	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
315	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
316	        String seed = telephone + lastName;
317	        try {
318	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
319	            byte[] hash = digest.digest(seed.getBytes(StandardCharsets.UTF_8));
320	            StringBuilder sb = new StringBuilder(hash.length * 2);
321	            for (byte b : hash) {
322	                sb.append(String.format("%02X", b));
323	            }
324	            return sb.substring(0, 8);
325	        }
326	        catch (NoSuchAlgorithmException e) {
327	            throw new IllegalStateException("SHA-256 not available", e);
328	        }
329	    }
