331	    /**
332	     * Whether any existing owner has the given derived identity key. This is the single basis for
333	     * duplicate detection: a create is rejected only when the whole key matches an existing owner
334	     * exactly. See {@link Owner#getIdentityKey()} for the key's definition.
335	     */
336	    @Override
337	    @Transactional(readOnly = true)
338	    public boolean existsOwnerWithIdentityKey(String identityKey) throws DataAccessException {
339	        if (identityKey == null) {
340	            return false;
341	        }
342	        return ownerRepository.findAll().stream()
343	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
344	    }
345	
346	    /**
347	     * Finds the id of an existing owner that {@code owner} soft-matches (a possible duplicate): one
348	     * that shares its lastName (case-insensitive) and postcode while carrying a <i>different</i>
349	     * telephone. This is a weaker match than the hard-duplicate identity key, so it is only meaningful
350	     * for an owner that is not itself a hard duplicate. When several owners match, the one with the
351	     * lowest id is returned; {@code null} is returned when there is no match (or lastName/postcode is
352	     * absent), meaning the owner is not a possible duplicate.
353	     */
354	    @Override
355	    @Transactional(readOnly = true)
356	    public Integer findPossibleDuplicateOwnerId(Owner owner) throws DataAccessException {
357	        if (owner == null || owner.getLastName() == null || owner.getPostcode() == null) {
358	            return null;
359	        }
360	        String lastName = owner.getLastName();
361	        String postcode = owner.getPostcode();
362	        String telephone = owner.getTelephone();
363	        return ownerRepository.findAll().stream()
364	            .filter(existing -> lastName.equalsIgnoreCase(existing.getLastName())
365	                && postcode.equals(existing.getPostcode())
366	                && !Objects.equals(telephone, existing.getTelephone()))
367	            .map(Owner::getId)
368	            .filter(Objects::nonNull)
369	            .min(Comparator.naturalOrder())
370	            .orElse(null);
371	    }
