415	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
416	            .count();
417	    }
418	
419	    /**
420	     * Computes an owner's deterministic household id: the first 12 upper-case hex characters of the
421	     * SHA-256 digest over the owner's normalized last name, a {@code '|'} separator and its postcode
422	     * ({@code normalizedLastName + '|' + postcode}). Owners that share a last name and postcode
423	     * therefore map to the same household id automatically, without any explicit linking. Returns
424	     * {@code null} when the last name or postcode is absent or blank, since no household can be
425	     * formed without both.
426	     */
427	    @Override
428	    @Transactional(readOnly = true)
429	    public String computeHouseholdId(Owner owner) throws DataAccessException {
430	        if (owner == null) {
431	            return null;
432	        }
433	        String normalizedLastName = normalizeHouseholdField(owner.getLastName());
434	        String postcode = owner.getPostcode();
435	        if (normalizedLastName == null || normalizedLastName.isBlank()
436	            || postcode == null || postcode.isBlank()) {
437	            return null;
438	        }
439	        return sha256UpperHex(normalizedLastName + "|" + postcode, 12);
440	    }
441	
442	    /**
443	     * Whether any existing owner already belongs to the household identified by the given
444	     * (deterministic) household id. This is the single basis for the household-duplicate rule:
445	     * owners that share a last name and postcode share a household id, so a matching existing owner
446	     * means the new owner is a household duplicate. Returns {@code false} when the id is absent.
447	     */
448	    @Override
449	    @Transactional(readOnly = true)
450	    public boolean existsOwnerInHousehold(String householdId) throws DataAccessException {
451	        if (householdId == null || householdId.isBlank()) {
452	            return false;
453	        }
454	        return ownerRepository.findAll().stream()
455	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
456	    }
457	
458	    /**
459	     * Counts the owners that belong to the household identified by the given (deterministic)
460	     * household id, i.e. the number of owners currently sharing it. Used to size a household for
461	     * the membership-points calculation. Returns {@code 0} when the id is absent.
462	     */
463	    @Override
464	    @Transactional(readOnly = true)
465	    public int countOwnersByHouseholdId(String householdId) throws DataAccessException {
466	        if (householdId == null || householdId.isBlank()) {
467	            return 0;
468	        }
469	        return (int) ownerRepository.findAll().stream()
470	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
471	            .count();
472	    }
473	
474	    /**
475	     * Normalizes a household-identity field for comparison by trimming, collapsing internal
476	     * runs of whitespace to a single space and lower-casing, so values that differ only in
477	     * whitespace or letter case are treated as equal.
478	     */
479	    private static String normalizeHouseholdField(String value) {
480	        if (value == null) {
481	            return null;
482	        }
483	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
484	    }
485	
486	    /**
487	     * Returns the first {@code length} upper-case hex characters of the SHA-256 digest of the
488	     * UTF-8 bytes of {@code seed}.
489	     */
490	    private static String sha256UpperHex(String seed, int length) {
491	        try {
492	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
493	            byte[] hash = digest.digest(seed.getBytes(StandardCharsets.UTF_8));
494	            StringBuilder sb = new StringBuilder(hash.length * 2);
495	            for (byte b : hash) {
496	                sb.append(String.format("%02X", b));
497	            }
